-- changeset lossrun:0008-v-claim-as-reported (changelog/0008-views.sql)
IF OBJECT_ID(N'dbo.SchemaChangeLog', N'U') IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0008-v-claim-as-reported' AND Author = N'lossrun' AND FileName = N'changelog/0008-views.sql') OR EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0008-v-claim-as-reported' AND Author = N'lossrun' AND FileName = N'changelog/0008-views.sql' AND MD5Sum <> N'76a08a438d0997a94b2d5909e495cc449de226f5627624bb6acff993941222a2')
    EXEC (N'CREATE OR ALTER VIEW dbo.vClaimAsReported
AS
SELECT ev.ClaimId,
       ev.DocumentId,
       MAX(CASE WHEN ev.ClaimField = N''claimNumber'' THEN ev.Value END)                                  AS ClaimNumber,
       MAX(CASE WHEN ev.ClaimField = N''claimantName'' THEN ev.Value END)                                 AS ClaimantName,
       TRY_CONVERT(date, MAX(CASE WHEN ev.ClaimField = N''dateOfInjury'' THEN ev.Value END))              AS DateOfInjury,
       MAX(CASE WHEN ev.ClaimField = N''status'' THEN ev.Value END)                                       AS Status,
       TRY_CONVERT(decimal(18, 2), MAX(CASE WHEN ev.ClaimField = N''indemnity.paid'' THEN ev.Value END))     AS IndemnityPaid,
       TRY_CONVERT(decimal(18, 2), MAX(CASE WHEN ev.ClaimField = N''indemnity.reserve'' THEN ev.Value END))  AS IndemnityReserve,
       TRY_CONVERT(decimal(18, 2), MAX(CASE WHEN ev.ClaimField = N''medical.paid'' THEN ev.Value END))       AS MedicalPaid,
       TRY_CONVERT(decimal(18, 2), MAX(CASE WHEN ev.ClaimField = N''medical.reserve'' THEN ev.Value END))    AS MedicalReserve,
       TRY_CONVERT(decimal(18, 2), MAX(CASE WHEN ev.ClaimField = N''expense.paid'' THEN ev.Value END))       AS ExpensePaid,
       TRY_CONVERT(decimal(18, 2), MAX(CASE WHEN ev.ClaimField = N''expense.reserve'' THEN ev.Value END))    AS ExpenseReserve,
       TRY_CONVERT(decimal(18, 2), MAX(CASE WHEN ev.ClaimField = N''total.incurred'' THEN ev.Value END))     AS TotalIncurred
FROM dbo.ExtractedValue AS ev
WHERE ev.ClaimId IS NOT NULL
  AND ev.DocumentRevision = (SELECT MIN(f.DocumentRevision) FROM dbo.ExtractedValue AS f WHERE f.DocumentId = ev.DocumentId)
GROUP BY ev.ClaimId, ev.DocumentId;');
GO
IF NOT EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0008-v-claim-as-reported' AND Author = N'lossrun' AND FileName = N'changelog/0008-views.sql') INSERT INTO dbo.SchemaChangeLog (Id, Author, FileName, OrderExecuted, ExecType, MD5Sum, Description) VALUES (N'0008-v-claim-as-reported', N'lossrun', N'changelog/0008-views.sql', 20, N'EXECUTED', N'76a08a438d0997a94b2d5909e495cc449de226f5627624bb6acff993941222a2', N'sqlcmd');
GO

-- changeset lossrun:0008-v-claim-as-adjusted (changelog/0008-views.sql)
IF OBJECT_ID(N'dbo.SchemaChangeLog', N'U') IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0008-v-claim-as-adjusted' AND Author = N'lossrun' AND FileName = N'changelog/0008-views.sql') OR EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0008-v-claim-as-adjusted' AND Author = N'lossrun' AND FileName = N'changelog/0008-views.sql' AND MD5Sum <> N'bfddaa6352bc4fd9ed378de2dcf7faf5eb3d84ec2635b67d211118ba0889571b')
    EXEC (N'CREATE OR ALTER VIEW dbo.vClaimAsAdjusted
AS
SELECT c.Id AS ClaimId, c.DocumentId, d.UploadId, d.QuoteId, d.CarrierName, d.ValuationDate, p.PolicyNumber, p.EffectiveDate, p.ExpirationDate,
       c.ClaimNumber, c.ClaimantName, c.DateOfInjury, c.DateReported, c.DateClosed, c.Status, c.ClaimType,
       c.IndemnityPaid, c.IndemnityReserve, c.IndemnityIncurred, c.MedicalPaid, c.MedicalReserve, c.MedicalIncurred,
       c.ExpensePaid, c.ExpenseReserve, c.ExpenseIncurred, c.TotalPaid, c.TotalReserve, c.TotalIncurred,
       (SELECT COUNT(*) FROM dbo.Override AS o WHERE o.ClaimId = c.Id) AS OverrideCount,
       c.ValidFromUtc AS AdjustedUtc
FROM dbo.Claim AS c
JOIN dbo.Document AS d ON d.Id = c.DocumentId
JOIN dbo.PolicyPeriod AS p ON p.Id = c.PolicyPeriodId;');
GO
IF NOT EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0008-v-claim-as-adjusted' AND Author = N'lossrun' AND FileName = N'changelog/0008-views.sql') INSERT INTO dbo.SchemaChangeLog (Id, Author, FileName, OrderExecuted, ExecType, MD5Sum, Description) VALUES (N'0008-v-claim-as-adjusted', N'lossrun', N'changelog/0008-views.sql', 21, N'EXECUTED', N'bfddaa6352bc4fd9ed378de2dcf7faf5eb3d84ec2635b67d211118ba0889571b', N'sqlcmd');
GO

-- changeset lossrun:0008-v-audit-trail (changelog/0008-views.sql)
IF OBJECT_ID(N'dbo.SchemaChangeLog', N'U') IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0008-v-audit-trail' AND Author = N'lossrun' AND FileName = N'changelog/0008-views.sql') OR EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0008-v-audit-trail' AND Author = N'lossrun' AND FileName = N'changelog/0008-views.sql' AND MD5Sum <> N'12968feae521ff862a8d33ed71e81a37b44914fde30c4fbc130f98eafcc0e651')
    EXEC (N'CREATE OR ALTER VIEW dbo.vAuditTrail
AS
SELECT a.Id, a.AtUtc, a.UserId, a.Role, a.Action, a.UploadId, a.DocumentId, a.DocumentRevision, a.ClaimId, a.FieldPath, a.OldValue, a.NewValue, a.Rationale,
       a.OverrideId, a.CatalogVersion, a.FormatRef, a.Source, a.CorrelationId,
       t.commit_time AS CommittedUtc, t.principal_name AS CommittedBy, l.ledger_transaction_id AS LedgerTransactionId
FROM dbo.AuditEvent_Ledger AS l
JOIN dbo.AuditEvent AS a ON a.Id = l.Id
JOIN sys.database_ledger_transactions AS t ON t.transaction_id = l.ledger_transaction_id;');
GO
IF NOT EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0008-v-audit-trail' AND Author = N'lossrun' AND FileName = N'changelog/0008-views.sql') INSERT INTO dbo.SchemaChangeLog (Id, Author, FileName, OrderExecuted, ExecType, MD5Sum, Description) VALUES (N'0008-v-audit-trail', N'lossrun', N'changelog/0008-views.sql', 22, N'EXECUTED', N'12968feae521ff862a8d33ed71e81a37b44914fde30c4fbc130f98eafcc0e651', N'sqlcmd');
GO

-- changeset lossrun:0008-v-cost-by-path (changelog/0008-views.sql)
IF OBJECT_ID(N'dbo.SchemaChangeLog', N'U') IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0008-v-cost-by-path' AND Author = N'lossrun' AND FileName = N'changelog/0008-views.sql') OR EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0008-v-cost-by-path' AND Author = N'lossrun' AND FileName = N'changelog/0008-views.sql' AND MD5Sum <> N'ac6450fcd15b8388c10d412e55fc5e22603f191fd4c6ab35a0a8cf782349b8a2')
    EXEC (N'CREATE OR ALTER VIEW dbo.vCostByPath
AS
SELECT dc.Path, d.CarrierName, COUNT(*) AS Documents, SUM(dc.CostUsd) AS CostUsd, AVG(dc.CostUsd) AS MeanCostUsd,
       SUM(dc.LlmCalls) AS LlmCalls, SUM(dc.Pages) AS Pages, SUM(dc.TokensIn) AS TokensIn, SUM(dc.TokensOut) AS TokensOut
FROM dbo.DocumentCost AS dc
LEFT JOIN dbo.Document AS d ON d.Id = dc.DocumentId
GROUP BY dc.Path, d.CarrierName;');
GO
IF NOT EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0008-v-cost-by-path' AND Author = N'lossrun' AND FileName = N'changelog/0008-views.sql') INSERT INTO dbo.SchemaChangeLog (Id, Author, FileName, OrderExecuted, ExecType, MD5Sum, Description) VALUES (N'0008-v-cost-by-path', N'lossrun', N'changelog/0008-views.sql', 23, N'EXECUTED', N'ac6450fcd15b8388c10d412e55fc5e22603f191fd4c6ab35a0a8cf782349b8a2', N'sqlcmd');
GO

