-- changeset lossrun:0009-app-user (changelog/0009-ledger-digest.sql)
IF OBJECT_ID(N'dbo.SchemaChangeLog', N'U') IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0009-app-user' AND Author = N'lossrun' AND FileName = N'changelog/0009-ledger-digest.sql') OR EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0009-app-user' AND Author = N'lossrun' AND FileName = N'changelog/0009-ledger-digest.sql' AND MD5Sum <> N'3606f8c8aef0f4df08313994eff8cbd408ae4689eada35b5ce5f048c82b3312f')
    EXEC (N'DECLARE @principal sysname = N''$(appPrincipalName)'';
IF @principal <> N'''' AND CAST(SERVERPROPERTY(''EngineEdition'') AS int) = 5
BEGIN
    DECLARE @name nvarchar(300) = QUOTENAME(@principal);
    DECLARE @sql nvarchar(max) =
        CASE WHEN DATABASE_PRINCIPAL_ID(@principal) IS NULL THEN N''CREATE USER '' + @name + N'' FROM EXTERNAL PROVIDER; '' ELSE N'''' END
        + N''ALTER ROLE db_datareader ADD MEMBER '' + @name + N''; ALTER ROLE db_datawriter ADD MEMBER '' + @name + N''; GRANT EXECUTE TO '' + @name + N'';'';
    EXEC sys.sp_executesql @sql;
END');
GO
IF NOT EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0009-app-user' AND Author = N'lossrun' AND FileName = N'changelog/0009-ledger-digest.sql') INSERT INTO dbo.SchemaChangeLog (Id, Author, FileName, OrderExecuted, ExecType, MD5Sum, Description) VALUES (N'0009-app-user', N'lossrun', N'changelog/0009-ledger-digest.sql', 25, N'EXECUTED', N'3606f8c8aef0f4df08313994eff8cbd408ae4689eada35b5ce5f048c82b3312f', N'sqlcmd');
GO

