-- changeset lossrun:0020-bump-quote-revision-proc (changelog/0020-quote-revision.sql)
IF OBJECT_ID(N'dbo.SchemaChangeLog', N'U') IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0020-bump-quote-revision-proc' AND Author = N'lossrun' AND FileName = N'changelog/0020-quote-revision.sql') OR EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0020-bump-quote-revision-proc' AND Author = N'lossrun' AND FileName = N'changelog/0020-quote-revision.sql' AND MD5Sum <> N'994146d2d01f9e6f62b7da574341a66a5f768d9603b0038ebb238e64c0204cfa')
    EXEC (N'CREATE OR ALTER PROCEDURE dbo.BumpQuoteRevision @quoteId nvarchar(128), @at datetime2(3), @cause nvarchar(32), @documentId nvarchar(128) = NULL,
    @documentRevision int = NULL, @revision int OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @revision = NULL;
    UPDATE dbo.QuoteRevision WITH (UPDLOCK, HOLDLOCK)
    SET @revision = Revision = Revision + 1, ChangedUtc = @at, Cause = @cause, DocumentId = @documentId, DocumentRevision = @documentRevision
    WHERE QuoteId = @quoteId;
    IF @revision IS NULL
    BEGIN
        SET @revision = 1;
        INSERT INTO dbo.QuoteRevision (QuoteId, Revision, ChangedUtc, Cause, DocumentId, DocumentRevision) VALUES (@quoteId, 1, @at, @cause, @documentId, @documentRevision);
    END;
END;');
GO
IF NOT EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0020-bump-quote-revision-proc' AND Author = N'lossrun' AND FileName = N'changelog/0020-quote-revision.sql') INSERT INTO dbo.SchemaChangeLog (Id, Author, FileName, OrderExecuted, ExecType, MD5Sum, Description) VALUES (N'0020-bump-quote-revision-proc', N'lossrun', N'changelog/0020-quote-revision.sql', 41, N'EXECUTED', N'994146d2d01f9e6f62b7da574341a66a5f768d9603b0038ebb238e64c0204cfa', N'sqlcmd');
GO

-- changeset lossrun:0020-bump-quote-revision-grant (changelog/0020-quote-revision.sql)
IF OBJECT_ID(N'dbo.SchemaChangeLog', N'U') IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.SchemaChangeLog WHERE Id = N'0020-bump-quote-revision-grant' AND Author = N'lossrun' AND FileName = N'changelog/0020-quote-revision.sql')
    EXEC (N'DECLARE @principal sysname = N''$(appPrincipalName)'';
IF @principal <> N'''' AND CAST(SERVERPROPERTY(''EngineEdition'') AS int) = 5 AND DATABASE_PRINCIPAL_ID(@principal) IS NOT NULL
BEGIN
    DECLARE @sql nvarchar(max) = N''GRANT EXECUTE ON dbo.BumpQuoteRevision TO '' + QUOTENAME(@principal) + N'';'';
    EXEC sys.sp_executesql @sql;
END');
GO
